{"hypothesis": "Count the iv bit-string length (gives MAGIC) and tabulate foo's per-bit behaviour with the known constants.", "code": "import re,ast
s=open('/workspace/challenge.py').read()
iv="1001001010011110100000001111010101100100110110010111101011011110111100100"
print("MAGIC guess", len(iv))
ns={}
for n in ['K1','K2','K3','K4','K5','K6']:
    m=re.search(r'^%s = (b.*)$'%n, s, re.M)
    ns[n]=ast.literal_eval(m.group(1))
print({k:len(v) for k,v in ns.items()})
def foo1(a,b,c,d):
    return (a&b&c&d)|(a&(b^1)&(c^1)&d)|(a&(b^1)&c&(d^1))|(a&b&(c^1)&(d^1))|((a^1)&b&(c^1)&d)|((a^1)&b&c&(d^1))
# check: f(a,b,c,d)=1 iff parity even and (a|b)
ok=all(foo1(a,b,c,d)==((a^b^c^d)==0 and (a or b)) for a in (0,1) for b in (0,1) for c in (0,1) for d in (0,1))
print("foo bit = even parity & (a|b):", ok)"}

