def bit(B,p): return (B[p]>>0)&1
from collections import Counter
res=Counter(); fails=[]
for p in range(73):
    k1,k2,k3,k4,k5,k6=[ns[n][p] for n in ['K1','K2','K3','K4','K5','K6']]
    ok_t={}
